  'Mais força no lado Terrorista e nas aberturas de round': { en: 'More strength on the T side and in round openings', es: 'Más fuerza en el lado Terrorista y en las aperturas de ronda' },
  'O time reage melhor após perder rounds e segura a vantagem': { en: 'The team reacts better after losing rounds and holds the lead', es: 'El equipo reacciona mejor tras perder rondas y mantiene la ventaja' },
  'Pressão total': { en: 'Full pressure', es: 'Presión total' },
