  'Controle de mapa': { en: 'Map control', es: 'Control de mapa' },
  'Duelos e agressão. Forte em pistol/force e no ataque; sofre quando atrás e no CT.': { en: 'Duels and aggression. Strong in pistol/force and on attack; struggles when behind and on CT.', es: 'Duelos y agresión. Fuerte en pistol/force y en el ataque; sufre cuando va por detrás y en CT.' },
  'Rounds estudados. Forte no 2º half, no clutch e no seu mapa; lento em pistols.': { en: 'Studied rounds. Strong in the 2nd half, in clutches and on its map; slow in pistols.', es: 'Rondas estudiadas. Fuerte en la 2ª mitad, en el clutch y en su mapa; lento en pistols.' },
  'Velocidade no T. Forte no ataque e em viradas; frágil segurando como CT.': { en: 'Speed on T. Strong on attack and comebacks; fragile holding as CT.', es: 'Velocidad en T. Fuerte en el ataque y en remontadas; frágil aguantando como CT.' },
  'Paciência e espaço. Forte no CT e em rounds longos; fraco em pistols e ritmo alto.': { en: 'Patience and space. Strong on CT and in long rounds; weak in pistols and high pace.', es: 'Paciencia y espacio. Fuerte en CT y en rondas largas; débil en pistols y ritmo alto.' },
  'Campo equilibrado. Bom para aprender o jogo.': { en: 'Balanced field. Good for learning the game.', es: 'Campo equilibrado. Bueno para aprender el juego.' },
  'Adversários afiados e campo mais forte. Cada veto conta.': { en: 'Sharp opponents and a stronger field. Every veto counts.', es: 'Rivales afilados y un campo más fuerte. Cada veto cuenta.' },
