  "Ninguém com a AWP neste mapa: o time joga só de rifle.": { en: "Nobody on the AWP on this map: the team plays rifles only.", es: "Nadie con la AWP en este mapa: el equipo juega solo con rifles." },
  "Dois AWPs: só o primeiro compra a AWP.": { en: "Two AWPers: only the first one buys the AWP.", es: "Dos AWPers: solo el primero compra la AWP." },
  "Sem IGL definido: quem tiver a melhor leitura chama.": { en: "No IGL set: whoever reads the game best makes the calls.", es: "Sin IGL definido: quien mejor lea el juego hace las llamadas." },
  "não é IGL: chama pior e duela pior (sem IGL de verdade o time perde força).": { en: "is not an IGL: calls worse and duels worse (without a real IGL the team loses strength).", es: "no es IGL: llama peor y duela peor (sin un IGL de verdad el equipo pierde fuerza)." },
  "Dois IGLs: só o primeiro chama.": { en: "Two IGLs: only the first one calls.", es: "Dos IGLs: solo el primero llama." },
