  "Abre o site no T e pega o primeiro contato.": { en: "Opens the site on T and takes first contact.", es: "Abre el site en T y toma el primer contacto." },
  "Entra colado no entry e troca a morte.": { en: "Follows the entry closely and trades the death.", es: "Entra pegado al entry y cambia la muerte." },
  "Joga longe do time, pega rotação e segura o pós-plant.": { en: "Plays away from the team, catches rotations and holds the post-plant.", es: "Juega lejos del equipo, caza rotaciones y aguanta el post-plant." },
  "Utilitária e flash pro time; troca de trás.": { en: "Utility and flashes for the team; trades from behind.", es: "Utilidad y flashes para el equipo; cambia desde atrás." },
  "Leva a AWP: segura ângulo no CT e abre pick no T.": { en: "Takes the AWP: holds angles on CT and opens picks on T.", es: "Lleva la AWP: aguanta ángulos en CT y abre picks en T." },
  "Chama o jogo. Quem não é IGL chama pior e duela pior.": { en: "Calls the game. A non-IGL calls worse and duels worse.", es: "Llama el juego. Quien no es IGL llama peor y duela peor." },
