  "Três no A. Muralha contra o ataque no A, site B aberto.": { en: "Three on A. A wall against A hits, B site left open.", es: "Tres en A. Muralla contra el ataque a A, site B abierto." },
  "Três no B. Muralha contra o ataque no B, site A aberto.": { en: "Three on B. A wall against B hits, A site left open.", es: "Tres en B. Muralla contra el ataque a B, site A abierto." },
  "Sai pra pegar informação. Pune o T lento, sofre com o rush.": { en: "Pushes out for info. Punishes slow T sides, suffers against rushes.", es: "Sale a buscar información. Castiga al T lento, sufre con el rush." },
  "Cede o site e retoma junto. Forte contra split, fraco contra o meio.": { en: "Gives up the site and retakes together. Strong against splits, weak against mid.", es: "Cede el site y retoma en grupo. Fuerte contra splits, débil contra el medio." },
