  "Cancelar troca": { en: "Cancel swap", es: "Cancelar cambio" },
  "Agora clique em quem entra no lugar de": { en: "Now click who comes in for", es: "Ahora haz clic en quien entra por" },
  "Os 5 titulares jogam as séries. Clique num jogador e depois noutro para trocar de lugar (vale a partir da próxima série). O banco entra sozinho se um titular se machucar.": { en: "The 5 starters play the series. Click a player and then another to swap places (applies from the next series). The bench comes in automatically if a starter gets injured.", es: "Los 5 titulares juegan las series. Haz clic en un jugador y luego en otro para cambiarlos de lugar (vale desde la próxima serie). El banquillo entra solo si un titular se lesiona." },
  "Titulares": { en: "Starters", es: "Titulares" },
  "perde ritmo, moral e valor se ficar muito tempo sem jogar": { en: "loses sharpness, morale and value if left too long without playing", es: "pierde ritmo, moral y valor si pasa mucho tiempo sin jugar" },
  "lesionado(s): na partida entra o reserva do banco (ou um jovem da base).": { en: "injured: the bench sub comes in for the match (or an academy youngster).", es: "lesionado(s): en el partido entra el suplente del banquillo (o un juvenil de la cantera)." },
