  "Acalmar o grupo": { en: "Calm the group", es: "Calmar al grupo" },
  "Funciona depois de bons resultados; em má fase soa falso.": { en: "Works after good results; in a bad run it sounds fake.", es: "Funciona tras buenos resultados; en mala racha suena falso." },
  "Funciona em má fase e com profissionais; irrita temperamentais e soa injusto quando o time vai bem.": { en: "Works in a bad run and with professionals; annoys hotheads and sounds unfair when the team is doing well.", es: "Funciona en mala racha y con profesionales; irrita a los temperamentales y suena injusto cuando el equipo va bien." },
  "Funciona com moral baixa ou conflitos no vestiário; alivia os atritos.": { en: "Works with low morale or dressing room conflicts; eases the friction.", es: "Funciona con moral baja o conflictos en el vestuario; alivia los roces." },
