  'Pós-plant convertido': { en: 'Post-plants converted', es: 'Post-plant convertido' },
  'Retakes (bomba plantada contra)': { en: 'Retakes (bomb planted against)', es: 'Retakes (bomba plantada en contra)' },
  'Rounds de CT ganhos no tempo': { en: 'CT rounds won on time', es: 'Rondas de CT ganadas por tiempo' },
